/// <summary>
/// MET_35503_Broken Cases, Randow weight items
/// </summary>
[ExtensionOf(classStr(SalesLineType_ReturnItem))]
final class METSalesLineType_ReturnItem_Extension
{
    
}

Method.Source:
/// <summary>
/// Determines if the expected return quantity is greater than the return lot in broken case senario
/// </summary>
/// <param name="_returnLine">
/// The return order line.
/// </param>
/// <returns>true if the expected return quantity is greater than the return lot; otherwise, false.</returns>
protected boolean isQuantityGreaterThanReturnLot(SalesLine _returnLine)
{        
    boolean ok = next isQuantityGreaterThanReturnLot(_returnLine);
    if(salesLine.METBrokenCaseForClaims || this.isInvoiceContainBrokenCaseReturn(_returnLine))
    {          
        
        Qty qtyRemain = UnitOfMeasureConverter::convert(_returnLine.invoicedInTotal() - this.findUsedReturnLotQtyByInvoiceUnit(_returnLine),
                        UnitOfMeasure::unitOfMeasureIdBySymbol(CustInvoiceTrans::findInventTransid(SalesLine.InventTransIdReturn).SalesUnit),
                        UnitOfMeasure::unitOfMeasureIdBySymbol(SalesLine.SalesUnit), NoYes::Yes, InventTable::itemProduct(salesLine.ItemId),
                        NoYes::Yes);
        ok =  abs(salesLine.ExpectedRetQty) > qtyRemain;
    }
   
    return ok;
    
}

    /// <summary>
    /// Determines if the invoice conatain broken case posting
    /// </summary>
    /// <param name="_returnLine">
    /// The return order line.
    /// </param>
    /// <returns>true if the invoice conatain broken case posting; otherwise, false.</returns>
    protected boolean isInvoiceContainBrokenCaseReturn(SalesLine _returnLine)
    {
        boolean hasRecord;
        SalesLine   metSalesLineStd;
        select firstonly RecId from metSalesLineStd
            where metSalesLineStd.InventTransIdReturn       == _returnLine.InventTransId &&
                  metSalesLineStd.METBrokenCaseForClaims    == NoYes::Yes;
        if(metSalesLineStd.RecId)
        {
            hasRecord=true;
        }

        return hasRecord;
    }

    /// <summary>
    /// find the used return lot quantity
    /// </summary>
    ///  <returns>real.</returns>
    protected real findUsedReturnLotQtyByInvoiceUnit(SalesLine _returnLine)
    {
        SalesLine metSalesLineReturn;
        Qty       metQtyInvUnit;
        while select sum(ExpectedRetQty) from metSalesLineReturn
            group by salesUnit
            where    metSalesLineReturn.InventTransIdReturn == _returnLine.InventTransId &&
                     metSalesLineReturn.InventTransId != salesLine.InventTransId
        {
            if(metSalesLineReturn.SalesUnit == CustInvoiceTrans::findInventTransid(SalesLine.InventTransIdReturn).SalesUnit)
            {
                metQtyInvUnit+=metSalesLineReturn.ExpectedRetQty;
            }
            else
            {
                metQtyInvUnit+= UnitOfMeasureConverter::convert(metSalesLineReturn.ExpectedRetQty,               
                                UnitOfMeasure::unitOfMeasureIdBySymbol(SalesLine.SalesUnit),
                                UnitOfMeasure::unitOfMeasureIdBySymbol(CustInvoiceTrans::findInventTransid(SalesLine.InventTransIdReturn).SalesUnit),
                                NoYes::Yes, InventTable::itemProduct(salesLine.ItemId), NoYes::Yes);
            }
        }

        SalesLine metSalesLineCreditNote;
        while select sum(SalesQty) from metSalesLineCreditNote
            group by salesUnit
            where   metSalesLineCreditNote.InventTransIdReturn == _returnLine.InventTransId &&
                    metSalesLineCreditNote.InventTransId != salesLine.InventTransId         &&
                    !metSalesLineCreditNote.ExpectedRetQty
        {
            if(metSalesLineCreditNote.SalesUnit == CustInvoiceTrans::findInventTransid(SalesLine.InventTransIdReturn).SalesUnit)
            {
                metQtyInvUnit+=metSalesLineReturn.ExpectedRetQty;
            }
            else
            {
                metQtyInvUnit+= UnitOfMeasureConverter::convert(metSalesLineCreditNote.ExpectedRetQty,               
                                UnitOfMeasure::unitOfMeasureIdBySymbol(SalesLine.SalesUnit),
                                UnitOfMeasure::unitOfMeasureIdBySymbol(CustInvoiceTrans::findInventTransid(SalesLine.InventTransIdReturn).SalesUnit),
                                NoYes::Yes, InventTable::itemProduct(salesLine.ItemId),NoYes::Yes);
            }
        }
        return abs(metSalesLineReturn.ExpectedRetQty) + abs(metSalesLineCreditNote.SalesQty);
    }
